seed=[(0,0),(0,1),(0,3),(1,1),(1,2),(2,0)]
def norm(coords):
 r0=min(r for r,c in coords); c0=min(c for r,c in coords)
 return sorted((r-r0,c-c0) for r,c in coords)
def variants(coords):
 out=set()
 # D4 reflect + rotations
 for refl in [False,True]:
  for k in range(4):
   pts=[]
   for r,c in coords:
    x,y=(r,-c) if refl else (r,c)
    for _ in range(k): x,y=y,-x
    pts.append((x,y))
   out.add(tuple(norm(pts)))
 return [list(x) for x in out]
